      "rank": 1,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Peter W. Shor",
        "Alexei Kitaev",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction established that quantum coherence can be protected and scalable quantum computation is physically conceivable.",
        "attribution": "Shor, Kitaev, and Steane made distinct foundational contributions to codes and fault-tolerant computation.",
        "maturity": "The principles have endured for decades and are now being tested in increasingly convincing logical-qubit experiments.",
        "uncertainties": [
          "Whether present demonstrations yet establish a sufficiently decisive route to fault-tolerant computing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided an exceptionally clean, controllable realization of quantum information processing and many-body quantum physics.",
        "attribution": "Cirac and Zoller supplied seminal architecture and gate proposals, while Blatt led decisive experimental realization.",
        "maturity": "The platform is reproducible across laboratories and has progressed from fundamental demonstrations to sophisticated processors.",
        "uncertainties": [
          "The discovery overlaps substantially with broader quantum-computing and quantum-simulation citations."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping while opening sensitive tests of fundamental physics.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye made major independent experimental advances.",
        "maturity": "Their extraordinary precision and reproducibility are firmly established internationally.",
        "uncertainties": [
          "The appropriate boundary between the invention and the many subsequent technical contributors."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Yakir Aharonov",
        "Michael V. Berry"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological phases fundamentally changed the understanding of quantum phase and have consequences across modern physics.",
        "attribution": "Aharonov's effect and Berry's phase are clearly identifiable, complementary landmark contributions.",
        "maturity": "Both phenomena are long established experimentally and conceptually, with broad downstream influence.",
        "uncertainties": [
          "Whether two historically distinct effects should properly be treated as one prize-worthy discovery."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made artificial atoms and microwave photons a controllable laboratory for quantum optics and processing.",
        "attribution": "Blais supplied crucial theoretical formulation, Wallraff the early experiment, and Schoelkopf the experimental platform; Girvin also merits serious consideration.",
        "maturity": "It is a robust, widely reproduced framework central to superconducting quantum circuits.",
        "uncertainties": [
          "It lies close to the scientific territory recognized by the 2025 superconducting-circuit prize.",
          "The four-name attribution exceeds the maximum number of laureates."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry created a powerful quantum method for measurements of acceleration, gravity, and fundamental constants.",
        "attribution": "Bordé and Pritchard developed essential concepts and techniques, and Kasevich delivered landmark interferometric demonstrations.",
        "maturity": "The methods are mature and used broadly in precision measurement.",
        "uncertainties": [
          "The field's many formative contributors make a three-person attribution difficult."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is an unusually deep theoretical bridge between quantum field theory, gravity, and strongly correlated systems.",
        "attribution": "Maldacena's duality is central, with Witten and Polyakov providing foundational related frameworks.",
        "maturity": "Its theoretical influence is immense and applications remain active.",
        "uncertainties": [
          "Direct empirical confirmation of the duality is lacking.",
          "The precise allocation of credit among its many conceptual antecedents is contested."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and time-reversal-invariant topological insulators revealed a new robust class of quantum matter.",
        "attribution": "Kane and Mele made the defining prediction, while Molenkamp led a pivotal experimental realization.",
        "maturity": "Topological-insulator physics is established across materials and has reshaped condensed-matter theory.",
        "uncertainties": [
          "Credit and scope overlap with related topological-insulator and quantum-anomalous-Hall candidates."
        ]
      }
    }
  ]
}
